// Actual Qt widgets and event loop; Window work signal disconnected from
// business execution. Shutdown stays connected to exercise real worker cleanup.
#define main native_embedded_main
#include "../src/main.cpp"
#undef main
#include <QTest>
#include <QTemporaryDir>
#include <iostream>
class UiProbe {
 static inline QJsonArray tests;static inline int workCount=0;static inline QString lastOp;static inline QJsonObject lastParams;
 static void check(bool ok,const char *name){if(!ok)throw Failure(QStringLiteral("ui_test_failed_")+QString::fromLatin1(name));tests.append(QString::fromLatin1(name));}
 static QJsonArray departments(){return QJsonArray{QJsonObject{{"code","shared_leaf"},{"name","Fixture department A"},{"first_department_code","rootA"},{"first_department_name","Fixture system A"}},QJsonObject{{"code","shared_leaf"},{"name","Fixture department B"},{"first_department_code","rootB"},{"first_department_name","Fixture system B"}}};}
 static QJsonObject department(const QString &code){return {{"status","complete"},{"business_success",true},{"hospital_code",code},{"result_kind","departments"},{"departments",departments()},{"metadata_cache_source","snapshot"},{"performance",QJsonObject{{"metadata_cache_hit",true},{"http_dispatches",0}}}};}
 static void installSnapshotFixture(const QString &root,const QByteArray &csv){QDir().mkpath(root+"/data");const QString stamp=QDateTime::currentDateTimeUtc().toString(Qt::ISODateWithMs);QJsonArray entries;for(const auto &pair:QList<QPair<QString,QString>>{{"H01","Offline hospital one"},{"H02","Offline hospital two"}}){const auto deps=departments();const auto digest=QString::fromLatin1(QCryptographicHash::hash(QJsonDocument(deps).toJson(QJsonDocument::Compact),QCryptographicHash::Sha256).toHex());entries.append(QJsonObject{{"hospital_code",pair.first},{"hospital_name",pair.second},{"fetched_at",stamp},{"department_count",deps.size()},{"departments_sha256",digest},{"departments",deps}});}QJsonObject manifest{{"schema_version",1},{"complete",true},{"source_hospital_csv_sha256",QString::fromLatin1(QCryptographicHash::hash(csv,QCryptographicHash::Sha256).toHex())},{"fetched_at",stamp},{"hospital_count",2},{"hospitals",entries}};QFile out(root+"/data/hospital_departments_snapshot.json");check(out.open(QIODevice::WriteOnly|QIODevice::Truncate),"snapshot_fixture_open");const auto raw=QJsonDocument(manifest).toJson(QJsonDocument::Compact);check(out.write(raw)==raw.size(),"snapshot_fixture_written");out.close();}
 static QJsonObject availability(){return {{"status","complete"},{"rows",QJsonArray{QJsonObject{{"date","20261109"},{"department_name","Fixture department"},{"doctor_name","Public fixture doctor"},{"period","Morning"},{"remaining",0},{"status",QString::fromUtf8("约满")},{"queried_at","2026-11-09T12:00:00Z"}}}},{"coverage",QJsonObject{{"coverage_scope","one_department_one_date"},{"selected_duty_date","20261109"},{"calendar_checked",false},{"calendar_dates",QJsonValue(QJsonValue::Null)},{"selected_date_evidence","doctor_detail"},{"query_strategy","doctor_detail_first"}}},{"performance",QJsonObject{{"http_dispatches",1}}}};}
 static void renewalCases(const QString &root){
  Window w(root,false);QObject::disconnect(&w,&Window::work,w.worker_,&Worker::execute);int work=0,availabilityWork=0;QString op;QJsonObject params;QObject::connect(&w,&Window::work,&w,[&](QString o,QJsonObject p){++work;op=o;params=p;if(o=="availability")++availabilityWork;});w.autoLoad_->setChecked(false);w.hospital_="H01";w.jobHospital_="H01";w.completed("departments",department("H01"));w.department_->setCurrentIndex(1);w.show();QApplication::processEvents();
  auto perf=[](int api,double age){return QJsonObject{{"session_api_used",api},{"session_age_seconds",age},{"http_dispatches",0}};};
  auto warmed=[&](int api=0,double age=0){w.completed("prewarm",{{"status","ready"},{"performance",perf(api,age)}});};
  auto available=[&](int api,double age){auto a=availability();auto p=perf(api,age);p["http_dispatches"]=1;a["performance"]=p;w.cancel_->store(false);w.busy_=true;w.jobHospital_=w.hospital_;w.jobTimer_.restart();w.completed("availability",a);};
  w.prewarm_->setChecked(true);check(w.warming_&&op=="prewarm"&&!params.value("renew_session").toBool(),"initial_prewarm_does_not_force_extra_renewal");check(!w.query_->isEnabled()&&!w.crawl_->isEnabled()&&!w.crawlWorkers_->isEnabled(),"warming_disables_query_and_catalog_controls");int before=work;w.query();w.crawlCatalog();check(work==before&&availabilityWork==0,"direct_query_and_crawl_rejected_during_warmup");warmed(1,20);const qint64 metadataFailureAge=w.sessionAgeMs();w.jobHospital_=w.hospital_;w.completed("departments",{{"status","failed"},{"failure","department_snapshot_unavailable"}});check(w.ready_&&w.sessionObserved_.isValid()&&w.sessionAgeMs()>=metadataFailureAge&&w.warmExpiry_.isActive(),"local_snapshot_failure_preserves_live_session");available(1,20);check(w.ready_&&w.query_->isEnabled(),"young_session_enables_query");const int rowCount=w.rows_->rowCount();const QString rowDoctor=w.rows_->item(0,2)->text();
  w.noteUserActivity();before=work;QMetaObject::invokeMethod(&w.warmExpiry_,"timeout",Qt::DirectConnection);check(work==before+1&&op=="prewarm"&&params.value("renew_session").toBool()&&w.warming_,"expiry_submits_one_forced_session_renewal");check(w.rows_->rowCount()==rowCount&&w.rows_->item(0,2)->text()==rowDoctor,"automatic_renewal_preserves_last_real_rows");check(!w.renewalCredit_&&!w.renewalPending_&&!w.query_->isEnabled(),"renewal_consumes_one_credit_and_gates_query");warmed();before=work;QMetaObject::invokeMethod(&w.warmExpiry_,"timeout",Qt::DirectConnection);check(work==before&&!w.warming_&&!w.ready_,"second_idle_expiry_does_not_submit_network_work");check(!w.query_->isEnabled(),"prewarm_enabled_expired_session_query_button_disabled");before=availabilityWork;int beforeRenew=work;w.query();check(availabilityWork==before&&work==beforeRenew+1&&op=="prewarm"&&params.value("renew_session").toBool(),"direct_query_after_expiry_only_renews_no_availability");warmed();
  w.noteUserActivity();before=work;available(6,5);check(!w.ready_&&!w.query_->isEnabled(),"six_api_budget_blocks_query_before_event_dispatch");QApplication::processEvents();check(work==before+1&&op=="prewarm"&&params.value("renew_session").toBool()&&w.warming_,"six_api_budget_proactively_forces_renewal");check(w.rows_->rowCount()==1,"budget_renewal_preserves_completed_result");warmed();
  w.observeSession(perf(2,40));const qint64 ageBefore=w.sessionAgeMs();QTest::qWait(20);w.jobHospital_=w.hospital_;w.completed("departments",department(w.hospital_));check(w.sessionAgeMs()>=ageBefore&&w.sessionApiUsed_==2,"local_department_render_does_not_reset_observed_session_age");w.department_->setCurrentIndex(1);w.ready_=false;w.renewalCredit_=false;w.updateControls();check(!w.query_->isEnabled(),"prewarm_checked_not_ready_query_is_disabled");w.prewarm_->setChecked(false);check(w.query_->isEnabled(),"explicit_prewarm_off_allows_cold_query_button");before=availabilityWork;w.query();check(availabilityWork==before+1&&op=="availability"&&w.busy_,"explicit_prewarm_off_direct_query_reaches_business_work");w.completed("availability",{{"status","failed"},{"failure","offline_fixture"}});
  w.prewarm_->setChecked(true);before=work;warmed(6,100);check(!w.ready_,"unusable_prewarm_does_not_enable_query");QApplication::processEvents();check(work==before+1&&op=="prewarm"&&params.value("renew_session").toBool(),"unusable_prewarm_forces_one_bounded_fresh_session");w.renewalPending_=true;w.completed("prewarm",{{"status","failed"},{"failure","offline_fixture"}});check(!w.renewalPending_&&!w.renewalCredit_&&!w.ready_&&!w.sessionObserved_.isValid(),"prewarm_failure_clears_queued_renewal_and_credit");before=work;QApplication::processEvents();check(work==before,"failed_prewarm_does_not_automatically_retry");
  w.noteUserActivity();w.startWarm();w.renewalPending_=true;w.prewarm_->setChecked(false);check(!w.renewalPending_&&!w.renewalCredit_&&w.cancel_->load(),"turning_prewarm_off_cancels_pending_renewal");w.completed("prewarm",{{"status","cancelled"},{"failure","cancelled_by_user"}});before=work;w.requestRenewal();w.startWarm();check(work==before,"disabled_prewarm_rejects_queued_work");
  w.prewarm_->setChecked(true);w.renewalPending_=true;w.stop();check(!w.renewalPending_&&!w.renewalCredit_&&!w.sessionObserved_.isValid()&&w.cancel_->load(),"stop_clears_renewal_and_observed_session");w.completed("prewarm",{{"status","cancelled"},{"failure","cancelled_by_user"}});before=work;w.requestRenewal();w.startWarm();QApplication::processEvents();check(work==before&&!w.warming_,"stop_blocks_already_queued_warm_and_renewal_calls");
  w.prewarm_->setChecked(false);w.prewarm_->setChecked(true);w.renewalPending_=true;w.close();check(w.closing_&&!w.renewalPending_&&!w.renewalCredit_,"close_clears_renewal_before_worker_shutdown");QElapsedTimer timer;timer.start();while(w.thread_.isRunning()&&timer.elapsed()<3000){QApplication::processEvents();QTest::qWait(2);}check(!w.thread_.isRunning(),"renewal_fixture_worker_closed_without_network");
 }
public:
 static QJsonObject run(const QString &out){
  QTemporaryDir tmp;check(tmp.isValid(),"temp_root");QDir().mkpath(tmp.path()+"/data");QFile csv(tmp.path()+"/data/hospitals.csv");check(csv.open(QIODevice::WriteOnly),"csv_open");const QByteArray csvBytes("hospital_code,hospital_name,area,level,address\nH01,Offline hospital one,Local,Test,Public fixture\nH02,Offline hospital two,Local,Test,Public fixture\n");csv.write(csvBytes);csv.close();Window w(tmp.path(),false);QObject::disconnect(&w,&Window::work,w.worker_,&Worker::execute);QObject::connect(&w,&Window::work,&w,[&](QString op,QJsonObject params){++workCount;lastOp=op;lastParams=params;});w.autoLoad_->setChecked(false);w.show();QApplication::processEvents();check(w.isVisible(),"actual_qt_window_visible");check(!w.query_->isEnabled(),"query_initial_disabled");w.hospitals_->setCurrentCell(0,0);w.debounce_.stop();QTest::mouseClick(w.load_,Qt::LeftButton);check(w.busy_&&lastOp=="departments"&&lastParams.value("hospital_code").toString()=="H01","load_click_requests_local_snapshot");w.completed("departments",{{"status","failed"},{"failure","department_snapshot_unavailable"}});check(!w.busy_&&w.status_->text().contains(QString::fromUtf8("本地科室快照尚未覆盖"))&&w.load_->isEnabled(),"missing_snapshot_explained_without_success");int beforeCrawl=workCount;QTest::mouseClick(w.crawl_,Qt::LeftButton);check(w.busy_&&lastOp=="crawl_all_departments"&&workCount==beforeCrawl+1&&!w.crawl_->isEnabled()&&w.stop_->isEnabled(),"crawl_button_starts_single_background_job");w.stop();w.completed("crawl_all_departments",{{"status","cancelled"},{"failure","cancelled_by_user"},{"completed_hospitals",0},{"hospital_count",2}});check(!w.busy_&&w.crawl_->isEnabled()&&w.status_->text().contains(QString::fromUtf8("进度可续跑")),"crawl_stop_renders_resumable_state");installSnapshotFixture(tmp.path(),csvBytes);const int beforeSnapshotLoad=workCount;QTest::mouseClick(w.load_,Qt::LeftButton);check(!w.busy_&&workCount==beforeSnapshotLoad&&w.last_.value("metadata_cache_source").toString()=="snapshot","complete_snapshot_load_is_local_and_rendered");check(!w.query_->isEnabled(),"loaded_placeholder_disabled");check(w.department_->count()==3,"same_leaf_parent_choices_preserved");w.department_->setCurrentIndex(2);check(w.query_->isEnabled()&&w.department_->currentData().toString()=="shared_leaf"&&w.department_->currentData(Qt::UserRole+1).toString()=="rootB","selected_parented_department_enables_query");
  w.date_->setDate(QDate(2026,11,9));int beforeQuery=workCount;QTest::mouseClick(w.query_,Qt::LeftButton);check(w.busy_&&!w.query_->isEnabled()&&!w.date_->isEnabled()&&workCount==beforeQuery+1&&lastOp=="availability","real_click_single_request_busy_controls");check(lastParams.value("department_code").toString()=="shared_leaf"&&lastParams.value("first_department_code").toString()=="rootB","real_click_sends_parent_identity");w.completed("availability",availability());check(!w.busy_&&w.rows_->rowCount()==1&&w.query_->isEnabled(),"complete_restores_controls");check(w.ready_&&w.connection_->text().contains(QString::fromUtf8("后续查询复用连接"))&&w.warmExpiry_.isActive(),"availability_success_marks_live_connection_ready");check(w.last_.value("coverage").toObject()==availability().value("coverage").toObject(),"doctor_first_coverage_preserved");check(w.performance_->text().contains(QString::fromUtf8("HTTP 1 次"))&&w.rows_->item(0,4)->text()=="0"&&w.rows_->item(0,5)->text()==QString::fromUtf8("约满"),"doctor_first_one_http_status_remaining_rendered");w.date_->setDate(w.date_->date().addDays(1));check(w.rows_->rowCount()==0&&!w.lastQuerySuccess_,"date_change_clears_rows");w.date_->setDate(QDate(2026,11,9));
  w.warming_=true;int count=workCount;QTest::mouseClick(w.refresh_,Qt::LeftButton);check(!w.busy_&&workCount==count&&w.last_.value("metadata_cache_source").toString()=="snapshot"&&w.department_->count()==3,"refresh_during_warm_uses_local_snapshot_only");w.warming_=false;
  w.warming_=true;w.pendingLoad_=false;w.pendingForce_=false;count=workCount;w.completed("prewarm",{{"status","failed"},{"failure","fixture"}});check(!w.ready_&&!w.pendingLoad_&&!w.pendingForce_&&workCount==count,"failed_warm_does_not_start_business_job");
  w.department_->setCurrentIndex(2);w.repeat_->setChecked(true);w.query();w.completed("availability",availability());check(w.repeatTimer_.isActive()&&w.interval_->minimum()==60,"repeat_success_minimum60");w.query();w.completed("availability",{{"status","failed"},{"failure","fixture"}});check(!w.repeatTimer_.isActive()&&!w.lastQuerySuccess_,"repeat_failure_stops");check(!w.ready_&&!w.warmExpiry_.isActive()&&w.connection_->text().contains(QString::fromUtf8("未就绪；查询失败，会话已关闭")),"availability_failure_clears_ready_connection_label");
  w.query();check(w.busy_,"start_before_stop");w.stop();w.completed("availability",availability());check(!w.busy_&&!w.lastQuerySuccess_&&w.last_.value("status").toString()=="cancelled","stop_late_success_rejected");
  w.jobHospital_=w.hospital_;w.completed("departments",department(w.hospital_));check(w.department_->count()==3&&w.last_.value("status").toString()=="complete","stop_then_valid_local_cache_allowed");w.department_->setCurrentIndex(2);w.cancel_->store(false);w.query();w.completed("availability",availability());check(w.rows_->rowCount()==1,"fixture_results_available_for_screenshot");auto reserved=availability();auto reservedPerf=reserved.value("performance").toObject();reservedPerf["session_api_used"]=7;reserved["performance"]=reservedPerf;w.busy_=true;w.completed("availability",reserved);check(!w.ready_&&!w.warmExpiry_.isActive()&&(w.connection_->text().contains(QString::fromUtf8("余量不足"))||w.connection_->text().contains(QString::fromUtf8("后台续期"))),"seven_api_calls_reserve_requires_connection_renewal");
  QDir().mkpath(QFileInfo(out).absolutePath());const QString screenshot=out+".png";check(w.grab().save(screenshot),"public_fixture_screenshot_saved");w.hospitals_->setCurrentCell(1,0);w.debounce_.stop();check(w.rows_->rowCount()==0&&w.department_->currentIndex()==0&&!w.query_->isEnabled(),"hospital_change_clears_scope_rows");w.close();QElapsedTimer timer;timer.start();while(w.thread_.isRunning()&&timer.elapsed()<3000){QApplication::processEvents();QTest::qWait(2);}check(!w.thread_.isRunning(),"close_real_worker_quits");QFile mainSource(QDir(defaultProjectRoot()).filePath("src/main.cpp"));check(mainSource.open(QIODevice::ReadOnly),"startup_policy_source_open");const QByteArray actualMain=mainSource.readAll();mainSource.close();check(actualMain.contains("Window window(root,!args.contains(\"--no-prewarm\"));"),"actual_main_defaults_to_background_prewarm");check(!QStringList{"program"}.contains("--no-prewarm")&&QStringList{"program","--no-prewarm"}.contains("--no-prewarm"),"explicit_no_prewarm_flag_preserved");Window warm(tmp.path(),true);QObject::disconnect(&warm,&Window::work,warm.worker_,&Worker::execute);int warmWork=0;QObject::connect(&warm,&Window::work,&warm,[&](QString op,QJsonObject){if(op=="prewarm")++warmWork;else throw Failure(QStringLiteral("unexpected_warm_fixture_business_work"));});warm.autoLoad_->setChecked(false);warm.show();QApplication::processEvents();check(warm.prewarm_->isChecked()&&warm.warming_&&warmWork==1&&!warm.query_->isEnabled(),"default_prewarm_submitted_before_query");QTest::qWait(90);warm.hospital_="H01";warm.jobHospital_="H01";warm.jobTimer_.restart();warm.completed("departments",department("H01"));QTest::qWait(25);warm.completed("prewarm",{{"status","ready"}});auto warmMatch=QRegularExpression(QStringLiteral("([0-9]+[.][0-9]+)")).match(warm.connection_->text());check(warmMatch.hasMatch()&&warmMatch.captured(1).toDouble()*1000>=90,"warmup_clock_not_reset_by_local_department_render");check(warm.ready_&&!warm.warming_&&warmWork==1,"local_render_does_not_submit_more_prewarm");warm.close();timer.restart();while(warm.thread_.isRunning()&&timer.elapsed()<3000){QApplication::processEvents();QTest::qWait(2);}check(!warm.thread_.isRunning(),"prewarm_fixture_worker_closed_without_network");renewalCases(tmp.path());
  return {{"status","PASS"},{"tests_passed",tests.size()},{"tests",tests},{"network_attempts",0},{"business_execution_connected",false},{"coverage_fixture",availability().value("coverage")},{"query_chain_executed",false},{"work_signals_observed",workCount},{"screenshot",screenshot},{"worker_closed",true}};
 }
};
int main(int argc,char**argv){QApplication app(argc,argv);app.setQuitOnLastWindowClosed(false);QString out=argc>1?QString::fromLocal8Bit(argv[1]):QStringLiteral("NATIVE_UI_OFFLINE_RESULT.json");try{auto r=UiProbe::run(out);if(!writeJson(out,r))return 3;std::cout<<QJsonDocument(r).toJson(QJsonDocument::Compact).constData()<<std::endl;return 0;}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 2;}}
